"use strict";
GUIDE_DATA_EN.sections.push({"id":"g32","part":4,"title":"Initiating the Project","blocks":[{"level":1,"text":"A project moves through four overarching phases, known as initiation, planning, execution, and closing"},{"level":1,"text":"Teamwork is essential for project success, as it involves collaborating with diverse individuals who possess different backgrounds, perspectives, skills, and talents"},{"level":1,"text":"Customizing the team structure to fit the project's needs is crucial"},{"level":1,"text":"Responsibility Assignment Matrix (RAM)"},{"level":2,"text":"Clarifies roles and responsibilities in a project, ensuring efficient task completion and effective communication"},{"level":2,"text":"It outlines the responsible, accountable, consulted, and informed individuals for each task"},{"level":1,"text":"Stakeholder engagement in project management involves building and managing relationships with stakeholders throughout the project's duration"},{"level":1,"text":"Performance measurement in projects involves clear, observable, and measurable objectives listed in the project charter"},{"level":2,"text":"Key Performance Indicators (KPIs)"},{"level":2,"text":"SMART Objectives"},{"level":2,"text":"Objective and Key Results (OKRs)"},{"level":1,"text":"The project charter outlines the project's parameters, purpose, expectations, and vision"},{"level":1,"text":"The scope statement provides detailed descriptions of project elements"},{"level":1,"text":"A records management plan is crucial during the initiation stage of a project to handle the generation of documentation effectively"},{"level":1,"text":"Project Kickoff"},{"level":2,"text":"Live meeting where the team comes together for the first time to create a shared understanding of the project's purpose, goals, and plan"}]},{"id":"g33","part":4,"title":"Team Roles and Responsibilities","blocks":[{"level":1,"text":"Teamwork is an absolute necessity to make a project successful"},{"level":1,"text":"Identify the people who will deliver the work"},{"level":1,"text":"Choose members who have the right skills for the job"},{"level":1,"text":"Project Manager (PM)"},{"level":2,"text":"Runs the day-to-day management of the project"},{"level":2,"text":"Project sponsor holds ultimate responsibility for the success or failure of the project, delegating operations to the PM"},{"level":2,"text":"Responsibilities of PM"},{"level":2,"text":"Building the project team and securing resources"},{"level":2,"text":"Building the project charter and defining the project’s scope"},{"level":2,"text":"Creating required project logs and processes, including the issue log, change log, and risk register"},{"level":2,"text":"Ensuring project deliverables are met which includes making sure team members have the right skills and resources for activity completion on the activity list"},{"level":2,"text":"Preparing and delivering project status updates"},{"level":2,"text":"Tracking the project’s progress and status when compared to the schedule and budget"},{"level":2,"text":"Managing vendor relationships"},{"level":1,"text":"Business Analyst (BA)"},{"level":2,"text":"Improves the final product and operates between the business and IT department like a translator"},{"level":2,"text":"Responsibilities of BA"},{"level":2,"text":"Helping to define the project"},{"level":2,"text":"Gathering business and technical requirements"},{"level":2,"text":"Ensuring requirements stay aligned to needs"},{"level":2,"text":"Interpreting business requirements"},{"level":2,"text":"Verifying deliverables against requirements"},{"level":2,"text":"Assisting with testing and validation of products"},{"level":1,"text":"Architect (Enterprise, Software, or Cloud)"},{"level":2,"text":"Design solutions by looking across organizations to identify how different systems interoperate and ensure that projects meet solution requirements"},{"level":2,"text":"Responsibilities of Architects"},{"level":2,"text":"Solution design"},{"level":2,"text":"System blueprints"},{"level":2,"text":"Evaluating systems against organizational standards"},{"level":1,"text":"Developer or Engineer"},{"level":2,"text":"Possesses specialized expertise in their field, like front-end or back-end development, writing code, etc."},{"level":2,"text":"Responsibilities of Developer"},{"level":2,"text":"Writing code to standards"},{"level":2,"text":"Building products according to the project plan or sprint backlog"},{"level":2,"text":"Reporting development progress to the project manager or product owner"},{"level":1,"text":"Tester or Quality Assurance"},{"level":2,"text":"Work closely with developers to build quality software, and help prevent errors from escaping into production, which could be a costly and time- consuming mistake"},{"level":1,"text":"Customer or End-User"},{"level":2,"text":"Some project teams will also include a customer or end-user on the team"},{"level":2,"text":"They can offer valuable insight and often lend perspective on the product’s usability and functionality"},{"level":1,"text":"Vendor"},{"level":2,"text":"Any third party you work with to procure resources is a vendor, and you may work with none or many vendors on a single project"},{"level":2,"text":"Responsibilities of Vendor"},{"level":2,"text":"Provide work outlined in contracts"},{"level":2,"text":"Maintain service level agreements"},{"level":2,"text":"Keep clear lines of communication open for business relationships"},{"level":1,"text":"Stakeholder"},{"level":2,"text":"They are the people or groups affected by projects, but they carry responsibilities for the project too"},{"level":2,"text":"Responsibilities of Stakeholder"},{"level":2,"text":"Must understand the project’s purpose and how it will affect them"},{"level":2,"text":"Be transparent about their support or lack of support"},{"level":2,"text":"Provide timely feedback on the project’s progress"},{"level":1,"text":"Subject Matter Expert (SME)"},{"level":2,"text":"The person you consult when you need somebody to explain a complex topic simply or solve advanced issues"},{"level":1,"text":"Project Team Member"},{"level":2,"text":"Any team member, regardless of their job title or role, is considered a project team member"},{"level":1,"text":"Core Team Members"},{"level":2,"text":"Also called “operational” team members because they work on day-to- day project operations"},{"level":1,"text":"Extended Team Members"},{"level":2,"text":"They work on the project part time and might split their time between multiple projects and their functional job"},{"level":1,"text":"Each member will need to be identified as either a core or extended member"},{"level":1,"text":"Extended team members will have varying levels of availability, business needs, staffing availability, and organizational structure affect each individual’s availability"},{"level":1,"text":"Functional member can be fully committed to project execution"},{"level":1,"text":"Members can be further categorized by percentage of time available, availability by phase, or availability on request"}]},{"id":"g34","part":4,"title":"Building the Project Team","blocks":[{"level":1,"text":"Identify your project team members based on skillsets, availability, and roles"},{"level":1,"text":"Choose the right people for the job"},{"level":1,"text":"Building the project team is often a continual process"},{"level":2,"text":"Define the project scope"},{"level":2,"text":"Select potential team members"},{"level":1,"text":"When the team is being assembled, the PM usually selects the team members"},{"level":2,"text":"Sponsors may also assign some key members early in the project"},{"level":1,"text":"You also want to capture additional information about the project team"},{"level":2,"text":"Job Position"},{"level":2,"text":"Availability"},{"level":2,"text":"Sub team or Grouping"},{"level":2,"text":"Responsibilities"},{"level":2,"text":"Preferred Contact Methods"},{"level":2,"text":"Manager"},{"level":2,"text":"Organization"},{"level":1,"text":"This leads us to the development of our project organizational chart"},{"level":2,"text":"This chart will look like a regular org chart, but will show project interfaces for the team"}]},{"id":"g35","part":4,"title":"Responsibility Assignment Matrix","blocks":[{"level":1,"text":"Responsibility Assignment Matrix (RAM)"},{"level":2,"text":"Clarifies who is responsible for completing and managing the activities in a project"},{"level":1,"text":"Team members will need to know what to do and whom to work with"},{"level":1,"text":"The RAM helps create a sense of project ownership and describes how team members and stakeholders work with project deliverables"},{"level":1,"text":"The roles fall into the following four categories: responsible, accountable, consulted, and informed"},{"level":1,"text":"RAM is first created in the project initiation phase"},{"level":1,"text":"Steps to Create a RAM"},{"level":2,"text":"List the activities for the project which will be placed within the first column of the matrix"},{"level":2,"text":"List the project team members, stakeholders, and other parties across the top of the available columns"},{"level":2,"text":"Identify those responsible for doing the work"},{"level":2,"text":"Mark an R for people that are responsible for the activities"},{"level":2,"text":"Mark an A for those accountable for the activities"},{"level":2,"text":"Mark a C for those responsible for consultation"},{"level":2,"text":"Mark an I for people that needs to be informed"},{"level":2,"text":"Optional Step: If it helps you and the team, use color-coding and grouping to make the chart easier to read"}]},{"id":"g36","part":4,"title":"Stakeholder Engagement","blocks":[{"level":1,"text":"Relationships between people really matter"},{"level":1,"text":"A firm handshake, eye contact, being polite, and timely correspondence goes very far when you’re building relationships and engaging with stakeholders"},{"level":1,"text":"Stakeholder engagement is how a PM builds and manages relationships with stakeholders throughout the life of the project"},{"level":1,"text":"Stakeholders will ask probing questions and challenge assumptions"},{"level":1,"text":"Soft skills are extremely important and should be on the imaginary tool belt of every project manager"},{"level":1,"text":"4 Steps to Stakeholder Engagement"},{"level":2,"text":"Identify key stakeholders"},{"level":2,"text":"Prioritize stakeholders"},{"level":2,"text":"Understand stakeholders"},{"level":2,"text":"Develop an engagement plan"},{"level":1,"text":"The highest-priority stakeholders need frequent and active engagement, and the lowest-priority stakeholders require minimal attention"},{"level":1,"text":"Impact Grid"},{"level":2,"text":"A matrix chart that sets high-low values for two stakeholder variables"},{"level":2,"text":"It measures how much stakeholders can influence a project’s trajectory and how much it will impact them"},{"level":2,"text":"The grid has four quadrants in order of priority"},{"level":2,"text":"High Power/High Impact"},{"level":2,"text":"Stakeholders have the most to gain and the most power"},{"level":2,"text":"It’s important to work with them to build support and ensure they are satisfied with the project’s progress."},{"level":2,"text":"High Power/Low Impact"},{"level":2,"text":"Stakeholders have enough influence that they could derail a project if they wanted"},{"level":2,"text":"The project has little impact on them, so they might have lower interest"},{"level":2,"text":"Low Power/High Impact"},{"level":2,"text":"Stakeholders have little power to change a project, so they are less likely to disrupt it"},{"level":2,"text":"Their work will change significantly because of the project"},{"level":2,"text":"Low Power/Low Impact"},{"level":2,"text":"Stakeholders have little power or impact on the project"},{"level":2,"text":"You are likely to find the lowest level of interest in this quadrant, but the situation could change"},{"level":1,"text":"The stakeholder engagement plan includes the following sections"},{"level":2,"text":"Stakeholder"},{"level":2,"text":"List the person or group"},{"level":2,"text":"Point of Contact"},{"level":2,"text":"If the stakeholder is not a person, list the person who represents the stakeholder"},{"level":2,"text":"Power"},{"level":2,"text":"List the power level from the Power/Impact Grid"},{"level":2,"text":"Influence"},{"level":2,"text":"List their impact level from the Power/Impact Grid"},{"level":2,"text":"Project Phase"},{"level":2,"text":"List the project phases that you will need to engage with them"},{"level":2,"text":"Engagement Needs"},{"level":2,"text":"Describe what they need or why they are a key stakeholder"},{"level":2,"text":"Engagement Approach"},{"level":2,"text":"List the type of engagement you will conduct from the Power/Impact Grid"},{"level":2,"text":"Methods"},{"level":2,"text":"Capture how you will communicate with them"},{"level":2,"text":"Frequency"},{"level":2,"text":"List a descriptive term of how often you will engage with the stakeholder"},{"level":1,"text":"The stakeholder engagement plan is not the same as the communication management plan"}]},{"id":"g37","part":4,"title":"Project Initiation Documents","blocks":[{"level":1,"text":"A strong launch for our project and a strong launch helps us create a shared understanding with all team members and stakeholders working on a project"},{"level":2,"text":"A shared, mutual understanding of the project creates an environment where everyone has the same perception of the project’s scope, timeline, team structure, and purpose"},{"level":1,"text":"A solid foundation helps prevent miscommunication, lost documentation, and scope creep throughout the project"},{"level":1,"text":"Artifacts can give great insight into how similar projects have already been executed"},{"level":1,"text":"Observe the lessons learned from past experiences and steer clear of obstacles"},{"level":1,"text":"Preparing for a project often begins with research"},{"level":1,"text":"Project Artifact"},{"level":2,"text":"Tangible item that was generated and used by people throughout the project"},{"level":2,"text":"Other examples of project artifacts"},{"level":2,"text":"Videos"},{"level":2,"text":"Audio Recordings"},{"level":2,"text":"Work Items"},{"level":2,"text":"Data Diagrams"},{"level":1,"text":"Studying the current artifacts helps you orient yourself to the project quickly"}]},{"id":"g38","part":4,"title":"Performance Measures & Timeline Charts","blocks":[{"level":1,"text":"When we talk about performance, it refers to clear, observable, and measurable project objectives which are listed in the project charter"},{"level":1,"text":"PMs use structured goal-oriented approaches to measure performance"},{"level":2,"text":"Key Performance Indicators (KPIs)"},{"level":2,"text":"It measures only the most crucial measures"},{"level":2,"text":"KPIs are measured regularly in an ongoing manner"},{"level":2,"text":"KPIs include targets and actuals"},{"level":2,"text":"Target"},{"level":2,"text":"A value or set of values that describe an acceptable range of performance"},{"level":2,"text":"KPIs measure both leading and lagging indicators"},{"level":2,"text":"Lagging Indicators"},{"level":2,"text":"These are reflective measures that can only be captured after the work is done and describe the realized success of a project or process"},{"level":2,"text":"Leading Indicators"},{"level":2,"text":"These are predictive measures that if perform well, the truly desired outcomes will improve"},{"level":2,"text":"SMART Objectives"},{"level":2,"text":"A simple way to create a goal"},{"level":2,"text":"An acronym that stands for"},{"level":2,"text":"SPECIFIC"},{"level":2,"text":"Explain exactly what we want to achieve"},{"level":2,"text":"MEASURABLE"},{"level":2,"text":"Have a quantifiable metric for success"},{"level":2,"text":"ACHIEVABLE"},{"level":2,"text":"Need to be realistic about the goal"},{"level":2,"text":"RELEVANT"},{"level":2,"text":"Helps you get a promotion or move positions"},{"level":2,"text":"TIME-BOUND"},{"level":2,"text":"Have a target end date"},{"level":2,"text":"Evaluate it against each SMART criterion and refine it"},{"level":2,"text":"Objective and Key Results (OKRs)"},{"level":2,"text":"Organizations apply OKRs to achieve results quickly"},{"level":2,"text":"They are meant to be aspirational and slightly out of reach"},{"level":2,"text":"They drive teams to deliver value that they didn’t think was possible"},{"level":2,"text":"OKRs create a two-part goal statement composed of objectives and key results"},{"level":2,"text":"These objectives take a \"less is more\" approach"},{"level":1,"text":"KPIs help you stabilize and protect systems"},{"level":1,"text":"SMART is a method for writing solid goals"},{"level":1,"text":"OKRs are used to create short term goals and generate change"},{"level":1,"text":"Project Roadmap"},{"level":2,"text":"High-level documents that share major progress points, such as new feature rollouts"},{"level":2,"text":"Highly visual and resembles the format and level of detail that you might read in a press release"},{"level":1,"text":"Milestone Chart"},{"level":2,"text":"Describes the milestone events, which are project checkpoints"},{"level":2,"text":"They look like a timeline and plot deadlines, check-ins, and critical dates over the course of the project"},{"level":1,"text":"Gantt Chart"},{"level":2,"text":"Shows relationships and dependencies between tasks"},{"level":2,"text":"Use the Gantt chart during the planning, execution, and closing phases"}]},{"id":"g39","part":4,"title":"Project Charter & Scope Statement","blocks":[{"level":1,"text":"Project Charter"},{"level":2,"text":"A concise, formal document that outlines the project’s parameters"},{"level":2,"text":"Created in the initiation phase and helps the team, stakeholders, sponsor, and PM achieve consensus on the importance of the project and how it will be executed"},{"level":2,"text":"Several Benefits of Project Charter"},{"level":2,"text":"Clarifies the project’s purpose and expectations for stakeholders"},{"level":2,"text":"Clarifies the PM’s role and authority level"},{"level":2,"text":"Simplified Creation Process of Project Charter"},{"level":2,"text":"Using a template will help tremendously because you'll repeatedly use the same fields of information"},{"level":2,"text":"The document should be short and simple"},{"level":2,"text":"Use clear and concise language"},{"level":2,"text":"Collaborate with your team to hammer out the timeline and risk assessment"},{"level":2,"text":"4 General Categories of Information"},{"level":2,"text":"General Project Information"},{"level":2,"text":"A header with standard information used for administrative purposes"},{"level":2,"text":"Project Name"},{"level":2,"text":"Description"},{"level":2,"text":"Version Number and Date"},{"level":2,"text":"Project Manager"},{"level":2,"text":"Project Sponsor"},{"level":2,"text":"Project Vision"},{"level":2,"text":"Includes fields that build a business justification and set expectations for the project’s outcomes"},{"level":2,"text":"Objectives"},{"level":2,"text":"Purpose"},{"level":2,"text":"Preliminary Scope"},{"level":2,"text":"Success Criteria"},{"level":2,"text":"Expected Benefits"},{"level":2,"text":"Organization (People)"},{"level":2,"text":"The people and groups affected by the project"},{"level":2,"text":"Stakeholders"},{"level":2,"text":"Customers"},{"level":2,"text":"Project Roles"},{"level":2,"text":"Team Members"},{"level":2,"text":"Project Organization"},{"level":2,"text":"Implementation Overview"},{"level":2,"text":"Factors that will affect the project during implementation"},{"level":2,"text":"Budget"},{"level":2,"text":"Risks"},{"level":2,"text":"Constraints"},{"level":2,"text":"Timelines"},{"level":2,"text":"Milestones"},{"level":2,"text":"Resource Requirements"},{"level":1,"text":"Project Charter is a summarized scope and boundaries & deliverables"},{"level":1,"text":"Scope Statement is a detailed description of multiple elements"},{"level":2,"text":"Scope statement is a living document"},{"level":2,"text":"In the preliminary scope statement, you will have the following"},{"level":2,"text":"Project Scope Description"},{"level":2,"text":"Summarizes the project’s intent and purpose"},{"level":2,"text":"Project Acceptance Criteria"},{"level":2,"text":"Details what the measurable outcomes of success looks like"},{"level":2,"text":"Project Deliverables"},{"level":2,"text":"Sets the project boundaries and identifies what the team will deliver for the scope"},{"level":2,"text":"Project Exclusions"},{"level":2,"text":"Sets the project boundaries for what is out of scope and what the project won’t deliver"},{"level":2,"text":"Assumptions and Constraints"},{"level":2,"text":"Assumptions section lists the project team’s collective assumptions and the constraints section lists the known constraints throughout the life of the project"}]},{"id":"g40","part":4,"title":"Records Management","blocks":[{"level":1,"text":"A document is a tangible artifact"},{"level":2,"text":"It contains data, which are facts, figures, and information"},{"level":1,"text":"Record"},{"level":2,"text":"An artifact that’s needed to run the project or the business"},{"level":2,"text":"Not every document is not a record"},{"level":1,"text":"Your records management plan should cover which records to keep and how to classify and protect the data"},{"level":2,"text":"Common types of artifacts into this plan"},{"level":2,"text":"Project Management Artifact"},{"level":2,"text":"Artifact used to manage the project, such as the project budget and stakeholder engagement plan"},{"level":2,"text":"Project Artifact"},{"level":2,"text":"Document created to move the project along, such as the required documentation and blueprints"},{"level":2,"text":"Legal Document"},{"level":2,"text":"Generates project contracts and other legally binding agreements"},{"level":2,"text":"Communication"},{"level":2,"text":"Includes meeting notes, status reports, and written communications"},{"level":1,"text":"Project Information"},{"level":2,"text":"Company asset and some of the information provides a competitive advantage against competitors"},{"level":1,"text":"4 Types of Data"},{"level":2,"text":"Public Data"},{"level":2,"text":"Information found on the company website and in public records"},{"level":2,"text":"Internal Data"},{"level":2,"text":"Available to anybody within the company"},{"level":2,"text":"Confidential Data"},{"level":2,"text":"Information is only available to authorized users either on a role or a case-by-case basis"},{"level":2,"text":"Restricted Data"},{"level":2,"text":"A top-secret data which access is severely restricted"},{"level":1,"text":"Classification of a document is dependent on the data it contains"},{"level":1,"text":"Requirements of a Records Management Plan"},{"level":2,"text":"The plan complies with organizational policy"},{"level":2,"text":"The records need to be organized and easy to find"},{"level":2,"text":"The plan is accessible to authorized users"},{"level":2,"text":"The plan needs to establish accepted communication channels"},{"level":1,"text":"Elements of a Records Management Plan"},{"level":2,"text":"Creation"},{"level":2,"text":"Defines naming conventions, file owners, and who can create files"},{"level":2,"text":"Storage and Retrieval"},{"level":2,"text":"Identifies where the team will store files and the file organizational structure"},{"level":2,"text":"Archival and Disposition"},{"level":2,"text":"Defines how to handle duplicate files and outdated files and how long the records will be archived after the project closes"}]},{"id":"g41","part":5,"title":"Kickoff","blocks":[{"level":1,"text":"Kickoff is the last step of the initiation phase in which the team has an approved project charter and a preliminary scope statement to boot"},{"level":1,"text":"The kickoff meeting is partly ceremonial but practical"},{"level":1,"text":"Kickoff’s purpose is to create a shared understanding with everybody"},{"level":1,"text":"Team members and stakeholders should have clear and aligned expectations for the project"},{"level":1,"text":"The kickoff meetings will vary in formality and structure Facilitating Effective Meetings"}]},{"id":"g42","part":5,"title":"Facilitating Effective Meetings","blocks":[{"level":1,"text":"Bad communication can sink a project very quickly"},{"level":1,"text":"Synchronous Communication"},{"level":2,"text":"Enables immediate information exchange and in-depth conversations but requires everyone to be available simultaneously"},{"level":1,"text":"Asynchronous Communication"},{"level":2,"text":"Offers flexibility but introduces delays and the possibility of messages going unread"},{"level":1,"text":"Formal communication follows official channels, while informal communication occurs casually within the organization"},{"level":1,"text":"Communication challenges can arise due to language barriers, geography, technology, and culture"},{"level":1,"text":"Meetings involve three key roles"},{"level":2,"text":"Target Audience"},{"level":2,"text":"Facilitator"},{"level":2,"text":"Scribe"},{"level":1,"text":"Informative meetings aim to disseminate information to the audience"},{"level":1,"text":"Decisive meetings, also known as decision-making meetings, involve one or more attendees making a choice regarding a project"},{"level":1,"text":"4 Main Types of Collaborative Meetings"},{"level":2,"text":"Focus Groups"},{"level":2,"text":"Workshops"},{"level":2,"text":"Application Reviews"},{"level":2,"text":"Brainstorming Sessions"},{"level":1,"text":"Staying organized as a project manager is crucial due to the multitude of meetings, emails, and interactions involved"},{"level":1,"text":"Conflict is an inevitable part of both personal and professional life, and it must be resolved responsibly"}]},{"id":"g43","part":5,"title":"Communication Methods","blocks":[{"level":1,"text":"Communication methods or modalities describe how information is shared/received"},{"level":1,"text":"4 Key Factors of Communication Methods"},{"level":2,"text":"Timing"},{"level":2,"text":"Format"},{"level":2,"text":"Formality"},{"level":2,"text":"Audience"},{"level":1,"text":"2 Types of Communication"},{"level":2,"text":"Synchronous Communication"},{"level":2,"text":"Also known as real-time communication, this could be a phone call, teleconference, or in-person meeting"},{"level":2,"text":"Synchronous communication is beneficial because you get all the information you need fast and can resolve confusion immediately"},{"level":2,"text":"The downside is that everybody needs to be available at the same time"},{"level":2,"text":"Asynchronous Communication"},{"level":2,"text":"Occurs when information exchanges include a delay, such as email and comments in a shared document"},{"level":2,"text":"Asynchronous communication offers flexibility; you can communicate with many people at once"},{"level":2,"text":"Delays may be unacceptable for urgent issues, and they can make simple questions drag on"},{"level":1,"text":"Format Considerations"},{"level":2,"text":"Written Communication"},{"level":2,"text":"Anything where exchanges occur through handwritten or typed messages"},{"level":2,"text":"Examples include letters through instant messages, emails, and Braille"},{"level":2,"text":"Verbal Communication"},{"level":2,"text":"Done orally, such as through face-to-face interactions, phone calls, teleconferencing, etc."},{"level":2,"text":"Nonverbal Communication"},{"level":2,"text":"Refers to the other signals sent during verbal communication, such as the body language and appearance"},{"level":1,"text":"Formal Communication"},{"level":2,"text":"Represents official communication channels which are the intentional, procedural channels where information flows and decisions are documented"},{"level":2,"text":"Project Phase Gate Reviews"},{"level":2,"text":"Help Desk Systems"},{"level":2,"text":"Company Memos"},{"level":2,"text":"Formal communication channels tend to be specific and rigid"},{"level":1,"text":"Informal Communication"},{"level":2,"text":"Describes all the unofficial information flows in an organization"},{"level":2,"text":"It includes a casual conversation between coworkers, group chatter before a meeting starts, and nonverbal communication during a meeting"},{"level":1,"text":"Know the audience and the level of formality in your language"},{"level":1,"text":"Internal Communication"},{"level":2,"text":"Includes recipients who work inside the organization"},{"level":2,"text":"The audience could consist of members from different projects, teams, or divisions, but everybody works at the same company"},{"level":1,"text":"External Communication"},{"level":2,"text":"Includes recipients who work outside the organization"},{"level":2,"text":"It tends to be formal, polished, and filtered"},{"level":2,"text":"Generally, need to be incredibly cautious when communicating with them"}]},{"id":"g44","part":5,"title":"Communication Challenges","blocks":[{"level":1,"text":"Language barriers, geography, technology, and culture can all pose challenges for communication"},{"level":1,"text":"Select appropriate communication formats or incorporate additional accommodations, such as including interpreters in live meetings and enabling closed captioning"},{"level":1,"text":"People who need more time to understand content might prefer asynchronous, written, or recorded communication"},{"level":1,"text":"Geographically distributed teams are more common than ever"},{"level":1,"text":"Be aware and respectful of time zone differences"},{"level":1,"text":"If the team is broadly spread, better opt for asynchronous communication"},{"level":1,"text":"Hold multiple meetings, use email and chat, or record meetings"},{"level":1,"text":"Technological barriers include any communication challenge related to technology"},{"level":1,"text":"Some team members might have slower internet or older hardware"},{"level":1,"text":"Anything you invest in removing technology barriers will make your teammates happier, efficient, and more productive"},{"level":1,"text":"Culture includes shared social customs, behavior, habits, and beliefs"},{"level":2,"text":"It can refer to any observable group, including age, gender, employer, profession, and hobby"},{"level":1,"text":"Companies often aim to create a strong workplace culture, which would unite everybody working for the company"},{"level":1,"text":"PMs need to be aware of the cultures within their project team and their implications"}]},{"id":"g45","part":5,"title":"Meeting Roles","blocks":[{"level":1,"text":"Meetings are a group effort, and several roles keep meetings on track"},{"level":1,"text":"3 Roles in a Meeting"},{"level":2,"text":"Attendees/Target Audience"},{"level":2,"text":"Group of people who need to be at the meeting"},{"level":2,"text":"The attendees on the list should be intentionally selected to keep the group small and productive"},{"level":2,"text":"Identify the meeting’s purpose and expected outcomes"},{"level":2,"text":"Select people who can make that happen"},{"level":2,"text":"Facilitator"},{"level":2,"text":"Guides the meeting’s progress"},{"level":2,"text":"The facilitator monitors the flow of the meeting and redirects the conversation"},{"level":2,"text":"Scribe"},{"level":2,"text":"Records notes for the meeting including the meeting minutes, action items, and follow ups"},{"level":2,"text":"All participants help the scribe in any meeting by answering questions, offering context, or sharing information via chat or email"},{"level":2,"text":"Following guidelines are helpful if you choose to implement the role"},{"level":2,"text":"Meetings that generate an official record (Board Meetings)"},{"level":2,"text":"Need for a written record and facilitation is expected to be taxing"},{"level":2,"text":"A session where the conversation will move quickly"}]},{"id":"g46","part":5,"title":"Informative Meetings","blocks":[{"level":1,"text":"Informative Meetings"},{"level":2,"text":"Disseminate information, informing the group of the information that needs to be spread"},{"level":1,"text":"Informative meetings are educational or persuasive in nature"},{"level":1,"text":"Use informational meetings when necessary, and make them as interactive as possible"},{"level":1,"text":"3 Subcategories of Informative Meetings"},{"level":2,"text":"Demonstrations and Presentations"},{"level":2,"text":"The presenter shares product features or offers training"},{"level":2,"text":"Demonstrations help a team’s outcome align with the stakeholder’s expectations"},{"level":2,"text":"Status Updates"},{"level":2,"text":"Gives updates on project progress at a specific point in time and varies in frequency and agenda"},{"level":2,"text":"Status meetings help the audience stay updated on the project without investing too much time in the minutiae too"},{"level":2,"text":"Stand-up"},{"level":2,"text":"Scrum uses daily stand-up meetings to keep every team member on the same page"},{"level":2,"text":"Stand-up meetings are short and usually last 15 minutes or less"},{"level":2,"text":"The intent is for team members to exchange information quickly, solve problems, and return to work"}]},{"id":"g47","part":5,"title":"Decisive Meetings","blocks":[{"level":1,"text":"Decisive Meeting is also called decision-making meetings where one or more attendees can make a decision"},{"level":2,"text":"Need to allow team members to exchange information, so aim for a smaller, interactive group; eight members or fewer works well"},{"level":1,"text":"People don’t recognize when they need to make decisions"},{"level":1,"text":"Examples of Decisive Meeting"},{"level":2,"text":"Task Setting"},{"level":2,"text":"Assigns work to individuals on a team"},{"level":2,"text":"Project Steering"},{"level":2,"text":"Includes the project manager and executive stakeholders"},{"level":2,"text":"The steering committee represents the voice of the customer and act as the governing body of the project without managing it"},{"level":2,"text":"They monitor the project’s progress and deliverables"},{"level":2,"text":"PM can use this type of meeting to secure decisions on funding and priorities"},{"level":2,"text":"Refinement Meeting"},{"level":2,"text":"Also known as product refinement or backlog refine meeting, which is the process of prioritizing the most valuable idea into a plan"}]},{"id":"g48","part":5,"title":"Collaborative Meetings","blocks":[{"level":1,"text":"Collaborative meetings are very interactive"},{"level":2,"text":"Need enough attendees to generate diverse ideas but not so many attendees that people can’t participate"},{"level":1,"text":"4 Main Kinds of Collaborative Meetings"},{"level":2,"text":"Focus Groups"},{"level":2,"text":"Research technique where a project manager gathers a group of customers or potential customers so that attendees can share their experiences, perceptions, needs, and problems related to a project or product"},{"level":2,"text":"They usually contain 6-12 participants and are held either in- person or online and have a structured agenda, like a prepared list of questions"},{"level":2,"text":"The PM facilitates and moderates the session, but the real value comes from the participants’ interaction"},{"level":2,"text":"Reduce bias by remaining neutral throughout the process or recruiting an objective party to moderate the session"},{"level":2,"text":"Several ways to facilitate a focus group"},{"level":2,"text":"Single-moderator"},{"level":2,"text":"Dual-moderator"},{"level":2,"text":"Dueling-moderator"},{"level":2,"text":"Two-way Focus Groups"},{"level":2,"text":"Allow one group to observe another focus group’s session"},{"level":2,"text":"Respondent-Moderator Focus Groups"},{"level":2,"text":"Allow one group to observe another focus group’s session"},{"level":2,"text":"Stakeholders can gain invaluable perspective from focus groups"},{"level":2,"text":"Workshop"},{"level":2,"text":"Working session where a group with shared interests gathers to exchange information and conduct research"},{"level":2,"text":"When creating a workshop agenda, include clear objectives that describe what people need to do or prepare for the meeting"},{"level":2,"text":"The diverse attendee list can create scheduling issues and challenge team dynamics"},{"level":2,"text":"Joint Application Review"},{"level":2,"text":"Specific type of workshop where customers take part in the design process of a product"},{"level":2,"text":"The development team can adjust their approach quickly and at a much lower cost"},{"level":2,"text":"Brainstorming"},{"level":2,"text":"Allows a group to generate many ideas rapidly"},{"level":2,"text":"Brainstorming sessions are usually fast-paced events where everybody can participate and they're usually pretty fun, in terms of business meetings of course"},{"level":2,"text":"4 Subcategories of Brainstorming"},{"level":2,"text":"Rapid"},{"level":2,"text":"Gives participants 3-5 minutes to write down ideas"},{"level":2,"text":"Reverse"},{"level":2,"text":"Looks at the problem from different angles"},{"level":2,"text":"Stop-and-Go"},{"level":2,"text":"Fights the quantity over quality issue"},{"level":2,"text":"Round-Robin"},{"level":2,"text":"Gives everyone an equal voice"}]},{"id":"g49","part":5,"title":"Meeting Artifacts","blocks":[{"level":1,"text":"It's important to stay organized as a project manager"},{"level":1,"text":"Meeting Agenda"},{"level":2,"text":"Includes the meeting’s purpose and schedule of activities or topics for the meeting"},{"level":2,"text":"POWER Start Agenda Technique is a great way to create meeting agendas"},{"level":2,"text":"Purpose"},{"level":2,"text":"Outcomes"},{"level":2,"text":"What’s In It For Me (WIIFM)"},{"level":2,"text":"Engagement"},{"level":2,"text":"Roles and Responsibilities"},{"level":1,"text":"Timeboxes"},{"level":2,"text":"Define how long the team will spend on each topic in a meeting"},{"level":1,"text":"Action Items"},{"level":2,"text":"Tasks that somebody will complete after the meeting"},{"level":1,"text":"Meeting Minutes"},{"level":2,"text":"Create a written record of key points"},{"level":1,"text":"Follow-Up"},{"level":2,"text":"Email for sharing the meeting minutes and additional information"}]},{"id":"g50","part":5,"title":"Conflict Management","blocks":[{"level":1,"text":"Conflict is inevitable it both our personal and professional lives"},{"level":1,"text":"A team needs time to stabilize and normalize"},{"level":1,"text":"Tuckman's Team and Group Development Model"},{"level":2,"text":"Forming"},{"level":2,"text":"Members come together for the first time and are meeting each other and sizing up the other members"},{"level":2,"text":"Storming"},{"level":2,"text":"Every problem in the process, large or small, gets amplified and questioned in this stage"},{"level":2,"text":"Norming"},{"level":2,"text":"Members work through their differences and respect each other"},{"level":2,"text":"Performing"},{"level":2,"text":"Members know how to work together and what to do"},{"level":2,"text":"Adjourning"},{"level":2,"text":"Team breaks apart, and the members move on to new projects"},{"level":1,"text":"2 Types of Conflict"},{"level":2,"text":"Substantive"},{"level":2,"text":"Emotional"},{"level":1,"text":"Both positive and negative conflicts need to be monitored and managed"},{"level":1,"text":"Common Causes of Conflict"},{"level":2,"text":"Personality differences are a big contributing factor"},{"level":2,"text":"Personal issues and external factors could play into this as well"},{"level":2,"text":"Competition over project resources stemming from budget constraints or perhaps there are conflicting priorities or proposals’"},{"level":2,"text":"Differences in writing styles can lead to miscommunication and conflict"},{"level":2,"text":"Formality"},{"level":2,"text":"Tone"},{"level":2,"text":"Presentation"},{"level":2,"text":"Cultural differences"},{"level":2,"text":"Tone"},{"level":2,"text":"Subtlety"},{"level":2,"text":"Word Choice"},{"level":2,"text":"Differences in typical expressiveness, body language, and personal space"},{"level":1,"text":"How do we resolve conflict?"},{"level":2,"text":"Effectively managing conflict requires a lifetime of practice"},{"level":2,"text":"You can manage and resolve conflict by applying five strategies:"},{"level":2,"text":"Smoothing"},{"level":2,"text":"Also called “accommodating”, this attempts to redirect conflicted parties away from the conflict"},{"level":2,"text":"Forcing"},{"level":2,"text":"Also called \"dominating\", this manages conflict by deciding what needs to happen to fix the issue, like an authoritarian"},{"level":2,"text":"Compromising"},{"level":2,"text":"People in the conflict share their insights and concede to change something but keep some part of their idea"},{"level":2,"text":"Collaborating"},{"level":2,"text":"Avoiding"},{"level":2,"text":"Ignoring the conflict; choose this option if the problem is too small to address and isn’t affecting the team’s performance"},{"level":1,"text":"Recognizing conflict early is key to successful conflict management"},{"level":1,"text":"9 Stages of Conflict Escalation"},{"level":2,"text":"Stages 1-3"},{"level":2,"text":"Parties still want to agree with each other and find a “win-win” solution"},{"level":2,"text":"Stages 4-6"},{"level":2,"text":"Conflict escalates into a win-lose scenario and parties vie for control"},{"level":2,"text":"Stages 7-9"},{"level":2,"text":"A fully lose-lose situation, people involved in the conflict are incapable of resolving it themselves Project Management Tools"}]},{"id":"g51","part":6,"title":"Project Management Tools","blocks":[{"level":1,"text":"Good software can reduce your overhead and create better lines of communication"},{"level":1,"text":"Project managers need to facilitate meetings and interactions, and using various media and meeting tools"},{"level":2,"text":"Calendaring Tools"},{"level":2,"text":"Conferencing Platforms"},{"level":2,"text":"Survey and Polling Tools"},{"level":2,"text":"Print Media"},{"level":1,"text":"People have different learning styles, with some being auditory learners, others tactile learners, and some visual learners"},{"level":1,"text":"Project managers often use diagrams"},{"level":2,"text":"Gantt Charts"},{"level":2,"text":"Flow Charts"},{"level":2,"text":"Decision Trees"},{"level":2,"text":"Data Flow Diagrams"},{"level":2,"text":"Mind Maps"},{"level":2,"text":"Quadrant Diagrams"},{"level":1,"text":"Collaboration tools are essential for project managers to communicate and work with their teams"},{"level":2,"text":"Multi-authoring editing software"},{"level":2,"text":"File sharing platforms"},{"level":2,"text":"Workflow and e-signature platforms"},{"level":2,"text":"Knowledge bases"},{"level":2,"text":"Whiteboards"},{"level":1,"text":"Communication tools, such as email, chat messaging, SMS, face-to-face communication, phone calls, video conferencing, and social media, are crucial for project managers to connect with their team members"},{"level":1,"text":"Communication Plan"},{"level":2,"text":"Outlines how stakeholders and team members will receive project updates and establishes recurring communication loops for critical information and feedback"},{"level":2,"text":"The key elements of a communication plan include"},{"level":2,"text":"Goals"},{"level":2,"text":"Stakeholders"},{"level":2,"text":"Team members"},{"level":2,"text":"Artifacts"},{"level":2,"text":"Channels"},{"level":2,"text":"Communication Recipients"},{"level":2,"text":"Frequency"},{"level":2,"text":"Outcomes"},{"level":1,"text":"Escalation Plan"},{"level":2,"text":"Helps resolve project issues by outlining problem scenarios, escalation levels, owners, and triggers"}]},{"id":"g52","part":6,"title":"Installation Options","blocks":[{"level":1,"text":"Installation options affect the total cost of ownership"},{"level":2,"text":"Cloud-based"},{"level":2,"text":"Give users access to applications through an Internet browser and usually called \"online software\" or \"online installations\""},{"level":2,"text":"Uses recurring fees"},{"level":2,"text":"Operational expense"},{"level":2,"text":"On-premise"},{"level":2,"text":"Installed in the cloud or on premise"},{"level":2,"text":"Initial investment"},{"level":2,"text":"Local Installation"},{"level":2,"text":"A variation of the on-premise solution and a common model for personal computers"},{"level":2,"text":"Software is installed on existing equipment"},{"level":1,"text":"User access considerations for the installation options"},{"level":2,"text":"Cloud software works across various devices via an Internet browser"},{"level":2,"text":"On-premise solutions give users access through an application on the devices"},{"level":2,"text":"In local installation, the user accesses the software from the device where it is installed"},{"level":1,"text":"How installation options affect pricing models"},{"level":2,"text":"Cloud-based"},{"level":2,"text":"Uses recurring fees"},{"level":2,"text":"Operational expense"},{"level":2,"text":"On-premise"},{"level":2,"text":"Initial investment"},{"level":2,"text":"Local Installation"},{"level":2,"text":"Software is installed on existing equipment"},{"level":1,"text":"Advantages of Installation Options"},{"level":2,"text":"Cloud-based solutions are a low-maintenance option"},{"level":2,"text":"On-premise installation allows companies to have total control over the installed software"},{"level":2,"text":"Local installation option provides reliable access to software"},{"level":1,"text":"Disadvantages of Installation Options"},{"level":2,"text":"Cloud has lower short-term costs but higher long-term costs"},{"level":2,"text":"Local and on-premise installations require a large upfront purchase of software licenses and hardware"},{"level":2,"text":"On-premise software product needs to be maintained, monitored, and updated"},{"level":2,"text":"The software in a local installation is only available on the computer that it is downloaded to"},{"level":2,"text":"Local installations require additional storage space on each device"}]},{"id":"g53","part":6,"title":"Meeting Tools","blocks":[{"level":1,"text":"Project managers need to facilitate meetings, workshops, and other interactions"},{"level":1,"text":"Calendaring Tool"},{"level":2,"text":"Simplifies the scheduling process by managing calendars and schedules"},{"level":1,"text":"Meetings with geographically distributed teams benefit from using conferencing platforms"},{"level":1,"text":"Survey and polling tools allow interaction among attendees without everybody speaking"},{"level":2,"text":"Surveys and polls are an excellent way to increase interaction during videoconference meetings"},{"level":1,"text":"Print Media"},{"level":2,"text":"Physical materials, such as posters, flip charts, brochures, and training manuals"}]},{"id":"g54","part":6,"title":"Productivity Tools","blocks":[{"level":1,"text":"Project tools help create records of project activities and their status and help automate many calculations and generate valuable reports and dashboards"},{"level":1,"text":"Help Desk System"},{"level":2,"text":"Users submit requests in the system, and automated workflows route the request to a person or group who can resolve them"},{"level":1,"text":"Ticketing systems are incredibly important organizational tools that systematically break down and prioritize work that needs to be done"},{"level":1,"text":"Some features of a project management software"},{"level":2,"text":"Task Planning"},{"level":2,"text":"Workflow Automation"},{"level":2,"text":"Resource Allocation"},{"level":1,"text":"Scheduling tools can automatically generate a Gantt chart, which is super helpful to stay organized"},{"level":1,"text":"Remember that your mileage will vary as you experiment with different software platforms"},{"level":1,"text":"Consider using a project management tool for your projects"},{"level":1,"text":"Different Productivity Tools"},{"level":2,"text":"Text Editors"},{"level":2,"text":"They allow to edit the text in a file, by adding, removing, or changing characters, but you cannot apply any formatting"},{"level":2,"text":"Text editors are helpful for writing code, capturing information in a clean environment, and clearing the formatting from text"},{"level":2,"text":"Word Processors"},{"level":2,"text":"Format text, insert objects, and create a visually appealing document"},{"level":2,"text":"Spreadsheets"},{"level":2,"text":"Works with data in tables, organize and modify data, complete mathematical calculations, and create graphs"},{"level":2,"text":"Presentation and Diagramming Software"},{"level":2,"text":"Creates slide decks, which are a series of visual pages that combine to tell a story"},{"level":2,"text":"List several topics that you’d like to discuss while presenting to the group"}]},{"id":"g55","part":6,"title":"Common Diagrams","blocks":[{"level":1,"text":"Diagrams make it easy to describe and share situations visually and it’s no surprise that every profession has a slew of diagram options"},{"level":1,"text":"Modern diagramming software has built-in templates to make creating diagrams even more straightforward"},{"level":1,"text":"Selection of Common Diagrams"},{"level":2,"text":"Gantt Chart"},{"level":2,"text":"A type of bar chart that shows time across the horizontal axis and a list of tasks or activities on the vertical axis with bars that represent the time each activity will occur"},{"level":2,"text":"Gantt charts are used for advanced scheduling"},{"level":2,"text":"Flowchart"},{"level":2,"text":"Flowcharts are also called “process flow” or “process diagrams”"},{"level":2,"text":"Visualizes a process, and can compress complicated work instructions into few charts"},{"level":2,"text":"Flowcharts are easy to read and understand; removing or changing steps is incredibly easy to demonstrate with a flowchart"},{"level":2,"text":"Decision Tree"},{"level":2,"text":"Describes a process that can have many decisions and many outcomes"},{"level":2,"text":"Use this type of chart when a single decision requires consideration of many factors"},{"level":2,"text":"Data Flow Diagram (DFD)"},{"level":2,"text":"Shows how information flows through a process or system"},{"level":2,"text":"This diagram type works particularly well for audiences that include people with technical and nontechnical expertise"},{"level":2,"text":"Mind Map"},{"level":2,"text":"Visualizes categories of information around a single theme, excellent for facilitating brainstorming activities"},{"level":2,"text":"Mind maps are excellent for facilitating brainstorming activities, thinking through problems, or consolidating information"},{"level":2,"text":"Quadrant"},{"level":2,"text":"A four-quadrant grid, one factor is placed on each axis, and each quadrant represents a high-low combination of the two factors"},{"level":2,"text":"Quadrant diagrams are an excellent tool for quickly assigning values or showing the relative priority of multiple options"}]},{"id":"g56","part":6,"title":"Collaboration Tools","blocks":[{"level":1,"text":"Project managers help organize and lead groups of people"},{"level":1,"text":"Collaboration tools allow people to work on documents at a place and time that will enable them to be most productive"},{"level":1,"text":"As a project manager, you should be aware and know when to implement:"},{"level":2,"text":"Multi-authoring Editing Software"},{"level":2,"text":"Allows multiple users to update the same file simultaneously"},{"level":2,"text":"The file also updates for all users as somebody updates it"},{"level":2,"text":"Disadvantage"},{"level":2,"text":"This format gives everyone the power to edit the final result, so you do have the risk of unauthorized changes and deletions"},{"level":2,"text":"File Sharing Platforms"},{"level":2,"text":"Allow for posting of a file in a single location and grant access to one or more users"},{"level":2,"text":"You can also manage permissions to control the files that people can access, edit, and download"},{"level":2,"text":"Sharing the files with somebody external to the company exposes the company’s assets to potential bad actors"},{"level":2,"text":"Always ensure file sharing practices meet your organization’s security requirements"},{"level":2,"text":"Workflow and e-Signature Platforms"},{"level":2,"text":"Workflow management systems that allow for the signing of documents using an Internet connection and electronic devices, like smartphones, tablets, or laptops"},{"level":2,"text":"Some users may be uncomfortable with electronic contracts"},{"level":2,"text":"Knowledge Bases"},{"level":2,"text":"Wiki"},{"level":2,"text":"Collaborative product where everybody with knowledge can contribute to its contents"},{"level":2,"text":"Knowledge Base"},{"level":2,"text":"More curated than a wiki and specific authors contribute to the knowledge base and cover particular topics"},{"level":2,"text":"Whiteboards"},{"level":2,"text":"Creates a virtual creative space that looks a lot like a physical whiteboard, offering a blank canvas that anyone can use to accomplish any creative task"},{"level":2,"text":"Virtual whiteboards allow more traffic and comfort for users and you can even save a copy of virtual whiteboards"}]},{"id":"g57","part":6,"title":"Communication Tools","blocks":[{"level":1,"text":"Email"},{"level":2,"text":"A common asynchronous communication technology"},{"level":2,"text":"Email is used to interact with people outside and inside the organization in the same channel"},{"level":2,"text":"Advantages"},{"level":2,"text":"Messages reach the recipient quickly"},{"level":2,"text":"Preserves historical records"},{"level":2,"text":"Works for lower-priority messages, longer messages, and mass communications"},{"level":2,"text":"Email is not the appropriate tool for an immediate response"},{"level":1,"text":"Chat/Instant Messaging"},{"level":2,"text":"A type of messaging service where messages are exchanged between two or more parties via an Internet connection"},{"level":2,"text":"Chat may not work with people inside and outside the organization at the same time"},{"level":2,"text":"Advantages"},{"level":2,"text":"Preserves historical records"},{"level":2,"text":"Conversational and informal"},{"level":2,"text":"Intends to be more real time"},{"level":2,"text":"Used for short conversations"},{"level":2,"text":"Do not use chat when capturing historical records or sharing long messages"},{"level":1,"text":"Texting or Short Message Services (SMS)"},{"level":2,"text":"A form of communication that generally transmits via cellular networks but can also be transmitted over the Internet"},{"level":2,"text":"Businesses use SMS messages for short, one-way text messages"},{"level":1,"text":"Talking Face-To-Face"},{"level":2,"text":"Meetings where to or more people are in the same room at the same time, exchanging information and ideas"},{"level":2,"text":"Meetings work when discussing sensitive topics and building relationships"},{"level":1,"text":"Telephone"},{"level":2,"text":"A form of synchronous communication that crosses geographical boundaries"},{"level":2,"text":"Landline"},{"level":2,"text":"Phones that are hardwired into buildings"},{"level":2,"text":"VoIP (Voice over Internet Protocol)"},{"level":2,"text":"Users receive a traditional phone number and use a handset to make phone calls"},{"level":2,"text":"Cellular"},{"level":2,"text":"Users receive standard phone numbers and transmit voice through cellular towers"},{"level":1,"text":"Video and Videoconference"},{"level":2,"text":"Blends the visibility of face-to-face meetings and phone calls to create a fully online meeting"},{"level":2,"text":"Videoconferencing uses specific software"},{"level":2,"text":"Users need access to reliable Internet, headsets, and cameras"},{"level":1,"text":"Enterprise Social Media"},{"level":2,"text":"Internal communication networks that encourage P2P connections and conversational tones"},{"level":2,"text":"Enterprise social media can be a tool for employees to network and communicate with each other"},{"level":2,"text":"Do not use enterprise social media to interact with people outside the organization"},{"level":2,"text":"Enterprise social media content tends to be shorter and shallow"}]},{"id":"g58","part":6,"title":"Elements of a Communication Plan","blocks":[{"level":1,"text":"Creating a formal plan reduces overhead and simplifies project management activities"},{"level":1,"text":"Communication Plan"},{"level":2,"text":"Documented strategy that outlines how stakeholders and team members will receive project updates"},{"level":2,"text":"Communication plans vary in depth and formality too, but every plan should be documented to provide clarity and manage expectations for those involved"},{"level":2,"text":"8 Common Elements of a Communication Plan"},{"level":2,"text":"Communication Goal"},{"level":2,"text":"Defines the purpose of the communication plan before it is created"},{"level":2,"text":"Stakeholders"},{"level":2,"text":"Identifies each stakeholder by name and records helpful information, like the person's title, relationship to the project, time zone, location, and preferred contact method"},{"level":2,"text":"Team Member"},{"level":2,"text":"Lists the name, job, time zone, location, and preferred contact method for each team member"},{"level":2,"text":"Artifact"},{"level":2,"text":"Identifies various communication artifacts needed to address the needs of the stakeholders and team members"},{"level":2,"text":"Communication Channel"},{"level":2,"text":"Selects the best communication channel for each artifact"},{"level":2,"text":"Recipient"},{"level":2,"text":"Identifies who will receive the communication"},{"level":2,"text":"Frequency"},{"level":2,"text":"Defines how often each communication needs to get shared"},{"level":2,"text":"Outcome"},{"level":2,"text":"Defines what must occur when communicating"}]},{"id":"g59","part":6,"title":"Develop a Communication Plan","blocks":[{"level":1,"text":"A communication plan sets the tone for the rest of the project by setting expectations with stakeholders and team members"},{"level":1,"text":"Transparency and cadence are important in a communication plan"},{"level":1,"text":"Steps in Developing a Communication Plan"},{"level":2,"text":"Identify the stakeholders"},{"level":2,"text":"List people that need to communicate regularly during the project"},{"level":2,"text":"Capture the stakeholder’s name, title, relationship to the project, and requirements"},{"level":2,"text":"Identify the communication preferences"},{"level":2,"text":"Learn how people prefer to be interacted with"},{"level":2,"text":"Define the type of information, how much detail is provided, and how to consume information"},{"level":2,"text":"Create a communication plan, share, and finalize plan"},{"level":2,"text":"Use the elements of a communication plan"},{"level":2,"text":"Communication Goal"},{"level":2,"text":"Stakeholders"},{"level":2,"text":"Team Member"},{"level":2,"text":"Artifact"},{"level":2,"text":"Communication Channel"},{"level":2,"text":"Recipient"},{"level":2,"text":"Frequency"},{"level":2,"text":"Outcome"},{"level":2,"text":"Use a template to help organize the information and ensure everything is covered"},{"level":2,"text":"The template may be linear and straightforward"},{"level":2,"text":"The share and finalize the plan step includes sending the draft to everyone involved"},{"level":2,"text":"Schedule the meeting"},{"level":2,"text":"Schedule the tasks needed to prepare for meetings"},{"level":2,"text":"The communication plan encompasses activities from a static document to an action plan"},{"level":2,"text":"Revise the plan"},{"level":2,"text":"Review the communication plan goals to ensure continued alignment with the plan"},{"level":1,"text":"Best practices when creating and implementing communication plans"},{"level":2,"text":"Planning is done to be organized, but also easier"},{"level":2,"text":"The communication plan standardizes the communication schedule and artifacts"},{"level":2,"text":"Adapt communication plans to meet the style and frequency of the audience"},{"level":2,"text":"Ask the team for a preferred meeting or way of communicating"}]},{"id":"g60","part":6,"title":"Build an Escalation Plan","blocks":[{"level":1,"text":"Escalation Plan"},{"level":2,"text":"Also called \"escalation matrix\", this describes problem scenarios that might occur in your project and how you can resolve them"},{"level":1,"text":"Escalation plan is critical to ensure that project issues are resolved quickly and effectively"},{"level":1,"text":"Any logs created later reflects the plan's intent"},{"level":1,"text":"Escalation plan is done during the project's initiation phase"},{"level":1,"text":"4 Primary Sections of an Escalation Plan"},{"level":2,"text":"Category"},{"level":2,"text":"Describes the type of escalation"},{"level":2,"text":"Level"},{"level":2,"text":"Indicates the escalation order"},{"level":2,"text":"Owner"},{"level":2,"text":"The person to be contacted when reaching any level"},{"level":2,"text":"Trigger"},{"level":2,"text":"Describes the conditions that initiate an escalation"},{"level":1,"text":"Escalation is a problem-solving technique"},{"level":1,"text":"Appropriate escalation is essential for effective project management"}]},{"id":"g61","part":6,"title":"Maintain Communication Records","blocks":[{"level":1,"text":"It is important to evaluate and update the records management plan whenever you create or modify the communication plan"},{"level":1,"text":"Consider the following when maintaining communication records"},{"level":2,"text":"Security"},{"level":2,"text":"Communication security plays a crucial role in protecting project information"},{"level":2,"text":"3 Different Types of Data"},{"level":2,"text":"Public Data"},{"level":2,"text":"No restrictions"},{"level":2,"text":"Confidential Data"},{"level":2,"text":"Limited access and only available to authorized users based on the role"},{"level":2,"text":"Critical Data"},{"level":2,"text":"Top secret and access are severely restricted"},{"level":2,"text":"When creating project communications, ensure the nature of the information is appropriate for the intended audience"},{"level":2,"text":"Archiving"},{"level":2,"text":"Communication archiving outlines how project documents are stored, including what to keep, where and how long to store it"},{"level":2,"text":"Comply with the organization’s records retention policy and information security requirements"},{"level":2,"text":"The PMO maintains a centralized archive of all completed projects"},{"level":2,"text":"Archives help in identifying best practices and lessons learned"},{"level":2,"text":"The project archive is also a source of analysis, where PMOs review data to identify trends within their functional area"},{"level":2,"text":"Compliance auditors review archives to audit organizational standards and procedures"},{"level":2,"text":"The archives also contain records that are required for legal compliance"},{"level":2,"text":"Vendor Selection Records"},{"level":2,"text":"Finalized Contracts"},{"level":2,"text":"Evaluation Materials"},{"level":2,"text":"Accurate project records are critical to protecting a company against potential litigation"},{"level":2,"text":"Integrity"},{"level":2,"text":"Communication integrity is when shared messages actually match reality"},{"level":2,"text":"Effective communication within a project requires capturing, centralizing, and reflecting the actual progress of the project"},{"level":2,"text":"Capturing and sharing meeting notes and notable progress and decisions in project materials ensures integrity"},{"level":2,"text":"Centralizing information from various platforms, such as planning platforms, emails, chats, and meetings, into a summarized communication artifact helps keep track of crucial decisions"},{"level":1,"text":"Communication artifacts should reflect the truth and actual progress of the project at all times, as trust in the data is essential"},{"level":1,"text":"Intentional and unintentional errors can compromise communication integrity Implementing Solution Design"}]},{"id":"g62","part":7,"title":"Implementing Solution Design","blocks":[{"level":1,"text":"Ensure that new software additions are compatible with existing products"},{"level":1,"text":"High-Level Design (HLD)"},{"level":2,"text":"Provides stakeholders with an overview of the project approach and what the final solution will look like"},{"level":1,"text":"Low-Level Design (LLD)"},{"level":2,"text":"Gives implementation instructions that the team can follow to execute the project"},{"level":1,"text":"Diminishing Returns"},{"level":2,"text":"Refers to the point at which additional resources or efforts invested will yield increasingly smaller or negligible improvements in project outcomes"},{"level":1,"text":"Pareto Principle"},{"level":2,"text":"States that approximately 80% of the project's results are typically derived from 20% of the efforts or activities"},{"level":1,"text":"IT Infrastructure"},{"level":2,"text":"Refers to the interconnected system of hardware, software, networks, and data centers"},{"level":2,"text":"Enables organizations to effectively manage and deliver information technology services, support business operations, and facilitate communication and data storage"},{"level":1,"text":"Data classification and handling in project management involves the systematic categorization, organization, and management of project data"},{"level":2,"text":"This is based on the project data’s sensitivity, confidentiality, and regulatory requirements"},{"level":1,"text":"Operational Security (OpSec)"},{"level":2,"text":"Refers to the measures and practices implemented to protect the confidentiality, integrity, and availability of project resources, data, and systems by mitigating risks, implementing access controls, monitoring activities, and responding to security incidents"}]},{"id":"g63","part":7,"title":"Solution Design Overview","blocks":[{"level":1,"text":"Solution Design"},{"level":2,"text":"Aims to optimize a project within the limitations of its operating environment and involves capturing the architecture and design requirements, testing requirements, technical risks, and analyzing tradeoffs"},{"level":1,"text":"The solution design process includes the creation of two documents"},{"level":2,"text":"High-level Design (HLD)"},{"level":2,"text":"Created in the analysis phase of the SDLC process, and it assesses technical feasibility"},{"level":2,"text":"HLD defines non-negotiable parameters and non-functional requirements (NFRs) and is used to select the solution"},{"level":2,"text":"Low-level Design (LLD)"},{"level":2,"text":"Created in the design phase of the SDLC process, and is a technical decision-making document that sorts out the project details"},{"level":2,"text":"LLD serves as a reference document for creating work, whether using a work breakdown structure (WBS) or user stories"},{"level":1,"text":"The final product is a blueprint for the project, which the project team will build based on the HLD and LLD"},{"level":2,"text":"Blueprint"},{"level":2,"text":"This is what the project team is going to build based upon these two documents, HLD and the LLD"},{"level":1,"text":"The solution design process aims to minimize the cost of changes in projects"},{"level":1,"text":"In the event the project team discovers that eight months into the project, the software fails to meet a critical requirement, this could result in a significant loss of time and money"},{"level":1,"text":"It is crucial for a solution design to identify the needs and compare different options early on to find an agreeable set of products that can significantly reduce these risks"},{"level":1,"text":"Collaboration in solution design builds confidence in the project"},{"level":1,"text":"Solution design reduces project risk in business environments"},{"level":1,"text":"Start with the end in mind by thinking about things early on and producing your high level and low-level designs"}]});
